import React, { useState, useEffect } from 'react';
import { AuthProvider } from './context/AuthContext';
import Navbar from './components/Navbar';
import Footer from './components/Footer';
import Home from './pages/Home';
import Catalog from './pages/Catalog';
import ProductPage from './pages/ProductPage';
import Profile from './pages/Profile';
import Auth from './pages/Auth';

function App() {
  const [currentPage, setCurrentPage] = useState('home');
  const [pageParams, setPageParams] = useState({});
  const [searchQuery, setSearchQuery] = useState('');

  // Обработка URL hash для навигации
  useEffect(() => {
    const handleHashChange = () => {
      const hash = window.location.hash.replace('#', '');
      if (hash) {
        const [page, param] = hash.split('/');
        setCurrentPage(page);
        setPageParams({ id: param });

        // Очищаем поиск при смене страницы
        if (page !== 'catalog') {
          setSearchQuery('');
        }
      } else {
        setCurrentPage('home');
        setSearchQuery('');
      }
    };

    window.addEventListener('hashchange', handleHashChange);
    handleHashChange();

    return () => window.removeEventListener('hashchange', handleHashChange);
  }, []);

  // Функция навигации
  const navigate = (page, params = {}) => {
    setCurrentPage(page);
    setPageParams(params);
    window.location.hash = page + (params.id ? `/${params.id}` : '');

    // Если переходим в каталог с поисковым запросом
    if (params.search) {
      setSearchQuery(params.search);
    }
  };

  // Рендер текущей страницы
  const renderPage = () => {
    switch (currentPage) {
      case 'catalog':
        return <Catalog searchQuery={searchQuery} />;
      case 'product':
        return <ProductPage productId={pageParams.id} />;
      case 'profile':
        return <Profile />;
      case 'auth':
        return <Auth />;
      default:
        return <Home />;
    }
  };

  return (
    <AuthProvider>
      <div className="min-h-screen bg-white">
        <Navbar onNavigate={navigate} setSearchQuery={setSearchQuery} />
        {renderPage()}
        <Footer />
      </div>
    </AuthProvider>
  );
}

export default App;
